const WIDTH = 24
const TRAIL = 6
const STEP_MS = 80
let active = false

const cells = (f: (i: number) => string) => Array.from({ length: WIDTH }, (_, i) => f(i)).join('')
const tickOf = () => Math.floor(Date.now() / STEP_MS)
const mod = (n: number, m: number) => ((n % m) + m) % m

// Every animation is a pure function of the tick and returns exactly WIDTH cells of plain text:
// the Spinner suffix drops ANSI colour codes, and wide emoji break the width.
const anim = {
  // a bright head bouncing back and forth with a trail
  sweep: (t: number) => {
    const period = WIDTH * 2 - 2
    const tick = t % period
    const forward = tick < WIDTH
    const pos = forward ? tick : period - tick
    const dir = forward ? 1 : -1
    return cells(i => {
      const d = (pos - i) * dir
      return d >= 0 && d < TRAIL ? (d === 0 ? '█' : '▓') : '░'
    })
  },
  wave: (t: number) => cells(i => '~≈'[(i + t) % 2]),
  flicker: (t: number) => cells(i => ((i * 7 + t * 13) % 9 === 0 ? 'ϟ' : '·')),
  fill: (t: number) => cells(i => (i < t % (WIDTH + 1) ? '●' : '○')),
  pulse: (t: number) => cells(i => '▁▁▂▅█▃▁▁'[(i + t) % 8]),
  drift: (t: number) => cells(i => ((i + t) % 6 === 0 ? 'z' : (i + t) % 6 === 3 ? 'Z' : ' ')),
  ripple: (t: number) => cells(i => '·○◎●◎○'[(i + t) % 6]),
  dash: (t: number) => cells(i => (mod(t - i, 5) === 0 ? '»' : '·')),
  twinkle: (t: number) => cells(i => ((i * 5 + Math.floor(t / 4) * 7) % 11 === 0 ? '*' : '·')),
  rain: (t: number) => cells(i => ((i * 3 + t) % 7 === 0 ? '/' : '·')),
  // a head with a flapping wing and a body, flying across and re-entering from the left
  glide: (t: number) => {
    const pos = t % (WIDTH + 6)
    const wing = Math.floor(t / 3) % 2 ? '^' : 'v'
    return cells(i => {
      const d = pos - i
      return d === 0 ? '>' : d === 1 ? wing : d > 1 && d < 6 ? '~' : '·'
    })
  },
}

type Name = keyof typeof anim

// First match on the spinner verb wins; anything else gets the fallback.
const rules: [RegExp, Name][] = [
  [/Thunderbolt|Pikachu/i, 'flicker'],
  [/Surfing|Splashing|Squirtle/i, 'wave'],
  [/Hatching|Evolving|Training/i, 'fill'],
  [/Healing|Potion/i, 'pulse'],
  [/Snorlax|Jigglypuff/i, 'drift'],
  [/Psychic|Mew|Lunala/i, 'ripple'],
  [/Razor Leaf|Bulbasaur/i, 'dash'],
  [/Dragonite/i, 'glide'],
]
const fallback: Name = 'sweep' // FALLBACK

export function animationFor(word: string): (t: number) => string {
  return anim[rules.find(([re]) => re.test(word))?.[1] ?? fallback]
}

export function register(on: any) {
  on('session.start', async ($: any, e: any, next: any) => {
    $.clock.every(STEP_MS, () => {
      if (active) $.ui.invalidate('ui.render')
    })
    return next(e)
  })

  on('turn.start', async ($: any, e: any, next: any) => {
    if (!e.agentId) active = true
    return next(e)
  })

  on('turn.complete', async ($: any, e: any, next: any) => {
    if (!e.agentId) active = false
    return next(e)
  })

  on('ui.render', { component: 'Spinner' }, async ($: any, e: any, next: any) =>
    next({ ...e, props: { ...e.props, suffix: ' ' + animationFor(e.props.word ?? '')(tickOf()) } }),
  )
}

